/* eslint-disable new-cap */

'use strict';

var zeros = require( '@stdlib/ndarray/zeros' );
var slice = require( '@stdlib/ndarray/slice' );
var E = require( '@stdlib/slice/multi' );
var S = require( '@stdlib/slice/ctor' );
var offsets = require( './../lib' );

// Create an array:
var x = zeros( [ 10, 10, 10, 10 ] );
// returns <ndarray>

// Define some slices:
var slices = [
	// :,:,:,:
	E( null, null, null, null ),

	// 5:10,4,2:4,::-1
	E( S( 5, 10 ), 4, S( 2, 4 ), S( null, null, -1 ) ),

	// :,:,2,:
	E( null, null, 2, null ),

	// 1,2,3,:
	E( 1, 2, 3, null ),

	// 1,3,::2,4::2
	E( 1, 3, S( null, null, 2 ), S( 4, null, 2 ) )
];

// Create ndarray views:
var views = [
	slice( x, slices[ 0 ] ),
	slice( x, slices[ 1 ] ),
	slice( x, slices[ 2 ] ),
	slice( x, slices[ 3 ] ),
	slice( x, slices[ 4 ] )
];

// Resolve the index offsets:
var out = offsets( views );
console.log( out );
